    function commandHelp(command, context) {
      const base = COMMAND_HELP_TEXT[String(command || "")] || "";
      if (!base) return "";
      const endpoint = context && context.dataset && context.dataset.endpointId ? "端点：" + context.dataset.endpointId + "。" : "";
      return endpoint + base;
    }

    function saveUiLayout(options) {
      var preserveOrder = !options || options.preserveOrder !== false;
      if (!preserveOrder) {
        currentUiLayout.order = Array.from(document.querySelectorAll("#mainColumn > [data-section]")).map((card) => card.dataset.section);
      } else if (!Array.isArray(currentUiLayout.order) || !currentUiLayout.order.length) {
        currentUiLayout.order = Array.from(document.querySelectorAll("#mainColumn > [data-section]")).map((card) => card.dataset.section);
      }
      currentUiLayout.collapsed = Object.assign({}, currentUiLayout.collapsed, collapseStateFromDom());
      currentUiLayout.resourceTreeChildren = normalizeResourceTreeChildOrders(currentUiLayout.resourceTreeChildren || {});
      currentUiLayout.columns = normalizeLayoutColumns(currentUiLayout.columns || {});
      currentUiLayout.treePinned = Boolean(currentUiLayout.treePinned);
      currentUiLayout.inspectorPinned = Boolean(currentUiLayout.inspectorPinned);
      currentUiLayout.inspectorCustomGroups = normalizeInspectorCustomGroups(currentUiLayout.inspectorCustomGroups);
      vscode.postMessage({ command: "saveUiLayout", layout: currentUiLayout });
    }

    function collapseStateFromDom() {
      const out = {};
      document.querySelectorAll("#mainColumn > [data-section]").forEach((card) => {
        out[card.dataset.section] = card.classList.contains("is-collapsed");
      });
      return out;
    }

    function normalizeUiLayout(layout) {
      layout = layout || {};
      const incoming = Array.isArray(layout.order) ? layout.order.map(String) : [];
      // 迁移旧布局：tasks / operations 卡片已合并为 execution；servers 已合入 sync
      const migratedIncoming = incoming.map((item) => (item === "tasks" || item === "operations" ? "execution" : item)).map((item) => (item === "servers" ? "sync" : item));
      const incomingSet = new Set(migratedIncoming);
      const standardOrder = RESOURCE_TREE_SECTION_ORDER.filter((item) => RESOURCE_TREE_SECTION_KEYS?.has(item));
      let order;
      if (layout.manual !== true) {
        order = standardOrder.slice();
      } else {
        order = migratedIncoming.filter((item) => RESOURCE_TREE_SECTION_KEYS?.has(item)).concat(RESOURCE_TREE_SECTION_ORDER.filter((item) => !incomingSet?.has(item)));
        if (order.length && order[order.length - 1] === "sync") order = standardOrder.slice();
      }
      const rawCollapsed = layout.collapsed && typeof layout.collapsed === "object" ? layout.collapsed : {};
      const collapsed = Object.assign({ servers: false, settings: false, sync: false, diagnostics: true, execution: false }, rawCollapsed);
      // 迁移旧布局：tasks 或 operations 折叠则 execution 折叠（仅当 execution 未显式设置）；servers 折叠迁移到 sync
      if (typeof rawCollapsed.execution !== "boolean") {
        collapsed.execution = Boolean(rawCollapsed.tasks) || Boolean(rawCollapsed.operations);
      }
      if (typeof rawCollapsed.sync !== "boolean" && typeof rawCollapsed.servers === "boolean") {
        collapsed.sync = Boolean(rawCollapsed.servers);
      }
      // 清理旧键，避免污染折叠签名（uiLayoutApplyKey / postRender 去重）
      delete collapsed.tasks;
      delete collapsed.operations;
      delete collapsed.servers;
      const resourceTreeChildren = normalizeResourceTreeChildOrders(layout.resourceTreeChildren || {});
      const columns = normalizeLayoutColumns(layout.columns || {});
      const inspectorCustomGroups = normalizeInspectorCustomGroups(layout.inspectorCustomGroups);
      return { order, collapsed, resourceTreeChildren, manual: Boolean(layout.manual), columns, treePinned: Boolean(layout.treePinned), inspectorPinned: Boolean(layout.inspectorPinned), inspectorCustomGroups };
    }

    function normalizeResourceTreeChildOrders(input) {
      const record = input && typeof input === "object" && !Array.isArray(input) ? input : {};
      const out = {};
      Object.keys(record).forEach((section) => {
        if (!RESOURCE_TREE_SECTION_KEYS?.has(section) || !Array.isArray(record[section])) return;
        const unique = [];
        record[section].map((value) => String(value || "").trim()).filter(Boolean).forEach((anchor) => {
          if (!unique.includes(anchor)) unique.push(anchor);
        });
        if (unique.length) out[section] = unique.slice(0, 80);
      });
      return out;
    }

    function normalizeLayoutColumns(columns) {
      const tree = clampNumber(Number(columns.tree || 280), 220, 420);
      const inspector = clampNumber(Number(columns.inspector || 360), 280, 520);
      return { tree, inspector };
    }

    function clampNumber(value, min, max) {
      if (!Number.isFinite(value)) return min;
      return Math.max(min, Math.min(max, Math.round(value)));
    }

    function normalizePinnedCommands(commands) {
      const source = Array.isArray(commands) ? commands : null;
      const cached = source ? pinnedCommandsNormalizationCache?.get(source) : undefined;
      if (cached) return cached;
      const unique = [];
      (source || []).forEach((command) => {
        const original = String(command || "");
        const value = original === "configureServerSyncScope" ? "configureCodeSyncIncludes" : original;
        if (PINNED_COMMAND_VALUES?.has(value) && !unique.includes(value)) unique.push(value);
      });
      const normalized = unique.slice(0, 8);
      if (source) pinnedCommandsNormalizationCache.set(source, normalized);
      return normalized;
    }

    function normalizeSavedButtonActions(actions, limit) {
      const source = Array.isArray(actions) ? actions : null;
      const normalizedLimit = limit || 24;
      const cacheKey = String(normalizedLimit) + ":" + normalizeActionSection(activeResourceSection || "overview");
      let variants = source ? savedButtonActionsNormalizationCache?.get(source) : undefined;
      const cached = variants && variants?.get(cacheKey);
      if (cached) {
        variants.delete(cacheKey);
        variants.set(cacheKey, cached);
        return cached;
      }
      const out = [];
      const seen = new Set();
      (source || []).forEach((item) => {
        const spec = normalizeSavedButtonAction(item);
        if (!spec || seen?.has(spec.id)) return;
        seen.add(spec.id);
        out.push(spec);
      });
      const normalized = out.slice(0, normalizedLimit);
      if (source) {
        if (!variants) {
          variants = new Map();
          savedButtonActionsNormalizationCache.set(source, variants);
        }
        variants.set(cacheKey, normalized);
        while (variants.size > SAVED_BUTTON_ACTION_NORMALIZATION_VARIANT_LIMIT) {
          const oldestKey = variants.keys().next().value;
          if (oldestKey === undefined) break;
          variants.delete(oldestKey);
        }
      }
      return normalized;
    }

    function normalizeSavedButtonAction(item) {
      const source = item && typeof item === "object" ? item : {};
      const command = String(source.command || "");
      if (!command || !webviewHandledCommands?.has(command)) return null;
      const section = normalizeActionSection(source.section || activeResourceSection || "overview");
      const payload = sanitizeActionPayload(source.payload || {});
      const label = compactText(String(source.label || featureCommandLabel(command) || command).replace(/\\s+/g, " ").trim(), 40);
      const id = String(source.id || actionSpecId(command, section, payload, label)).slice(0, 240);
      return {
        id,
        command,
        label: label || command,
        section,
        payload,
        confirm: Boolean(source.confirm),
        danger: Boolean(source.danger),
        batch: Boolean(source.batch),
        configScope: String(source.configScope || payload.configScope || "").slice(0, 80)
      };
    }

    function normalizeActionSection(section) {
      const value = String(section || "overview");
      if (value === "tasks" || value === "operations") return "execution";
      if (value === "servers") return "sync";
      if (RESOURCE_TREE_SECTION_KEYS?.has(value)) return value;
      if (value.startsWith("server")) return "sync";
      return "overview";
    }

    function sanitizeActionPayload(payload) {
      const out = {};
      SAVED_ACTION_PAYLOAD_KEYS.forEach((key) => {
        const value = payload && payload[key];
        if (value === undefined || value === null || value === "") return;
        if (typeof value === "number" || typeof value === "boolean") out[key] = value;
        else out[key] = String(value).slice(0, 500);
      });
      return out;
    }

    function actionSpecId(command, section, payload, label) {
      const payloadKey = Object.keys(payload || {}).sort().map((key) => key + "=" + String(payload[key])).join("|");
      return [section || "overview", command, payloadKey, label || ""].join("|");
    }

    function savedActionSame(a, b) {
      if (!a || !b) return false;
      return a.id === b.id || actionSpecId(a.command, a.section, a.payload || {}, a.label) === actionSpecId(b.command, b.section, b.payload || {}, b.label);
    }

    function defaultPinnedSpec(command) {
      return normalizeSavedButtonAction({ command, label: featureCommandLabel(command), section: "overview", payload: {}, id: "legacy:" + command });
    }

    // legacy detail/pinned actions removed; inspectorCustomGroups is the supported path.

    var INSPECTOR_CUSTOM_GROUP_SECTION_ORDER = ["sync", "plans", "gpu", "tmux", "execution", "results"];
    var INSPECTOR_CUSTOM_GROUP_STATIC_TITLES = { sync: "运行环境准备", plans: "实验准备", gpu: "GPU 状态", tmux: "TMUX 会话 / 窗口 / 窗格", execution: "运行进度", results: "结果文件" };
    var INSPECTOR_CUSTOM_GROUP_LEGACY_SECTIONS = { "基础设施": ["sync"], "发布": ["sync"], "实验": ["plans", "results"], "运维": [], "执行": ["execution"], "资源": ["gpu"], "TMUX 会话": ["tmux"] };
    var INSPECTOR_CUSTOM_GROUP_LEGACY_TARGETS = { "基础设施": ["运行环境准备"], "发布": ["运行环境准备"], "实验": ["实验准备", "结果文件"], "结果与归档": ["结果文件"], "运维": [], "执行": ["运行进度"], "资源": ["GPU 状态"], "TMUX 会话": ["TMUX 会话 / 窗口 / 窗格"] };

    var INSPECTOR_CUSTOM_GROUP_FALLBACK = ["运行环境准备", "实验准备", "GPU 状态", "TMUX 会话 / 窗口 / 窗格", "运行进度", "结果文件"];

    function inspectorCustomGroupTitles() {
      try {
        var cards = null;
        try { cards = document.querySelectorAll("#mainColumn>[data-section]"); } catch (e) { cards = null; }
        if (cards && cards.length) {
          var out = [];
          var seenSec = {};
          Array.prototype.forEach.call(cards, function(card) {
            var sec = String((card && card.dataset && card.dataset.section) || (card && card.getAttribute ? card.getAttribute("data-section") : "") || "").trim();
            if (!sec || sec === "servers" || sec === "settings" || sec === "diagnostics") return;
            if (seenSec[sec]) return;
            seenSec[sec] = true;
            var title = String((card && card.dataset && card.dataset.title) || (card && card.getAttribute ? card.getAttribute("data-title") : "") || "").trim();
            if (!title) title = String(INSPECTOR_CUSTOM_GROUP_STATIC_TITLES[sec] || "").trim();
            if (!title || title === "诊断与自检") return;
            if (out.indexOf(title) === -1) out.push(title);
          });
          if (out.length) return out;
        }
      } catch (e) {}
      try {
        var fb = [];
        INSPECTOR_CUSTOM_GROUP_SECTION_ORDER.forEach(function(sec) {
          var t = String(INSPECTOR_CUSTOM_GROUP_STATIC_TITLES[sec] || "").trim();
          if (t && fb.indexOf(t) === -1) fb.push(t);
        });
        if (fb.length) return fb;
      } catch (e) {}
      return INSPECTOR_CUSTOM_GROUP_FALLBACK.slice();
    }

    function inspectorSectionsForCustomGroup(groupTitle) {
      var want = String(groupTitle || "");
      // 诊断不显示右侧：旧 diagnostics 键直接丢弃（运维提示并入主列诊断卡，不在右侧建组）
      if (want === "诊断与自检" || want === "diagnostics" || want === "运维") return [];
      var out = [];
      try {
        var domMap = {};
        try {
          var cards = document.querySelectorAll("#mainColumn>[data-section]");
          Array.prototype.forEach.call(cards, function(card) {
            var sec = String((card && card.dataset && card.dataset.section) || (card && card.getAttribute ? card.getAttribute("data-section") : "") || "").trim();
            var title = String((card && card.dataset && card.dataset.title) || (card && card.getAttribute ? card.getAttribute("data-title") : "") || "").trim();
            if (!sec || !title) return;
            if (sec === "servers" || sec === "settings") return;
            if (!title) title = String(INSPECTOR_CUSTOM_GROUP_STATIC_TITLES[sec] || "").trim();
            if (!title) return;
            if (!domMap[title]) domMap[title] = [];
            if (domMap[title].indexOf(sec) === -1) domMap[title].push(sec);
          });
        } catch (e) {}
        if (domMap[want] && domMap[want].length) return domMap[want].slice();
        Object.keys(INSPECTOR_CUSTOM_GROUP_STATIC_TITLES).forEach(function(sec) {
          if (String(INSPECTOR_CUSTOM_GROUP_STATIC_TITLES[sec]) === want && out.indexOf(sec) === -1) out.push(sec);
        });
        if (out.length) return out;
        var legacy = INSPECTOR_CUSTOM_GROUP_LEGACY_SECTIONS[want];
        if (legacy && legacy.length) return legacy.slice();
        try {
          var model = typeof resourceTreeStaticModelCached === "function" ? resourceTreeStaticModelCached() : null;
          if (model) {
            Object.keys(model).forEach(function(section) {
              var entry = model[section];
              if (String((entry && entry.label) || "") === want && out.indexOf(section) === -1) out.push(section);
            });
            if (want === "基础设施" && out.indexOf("sync") === -1) out.push("sync");
          }
        } catch (e) {}
      } catch (e) {}
      return out;
    }

    function normalizeInspectorCustomGroups(input) {
      var out = {};
      var record = input && typeof input === "object" && !Array.isArray(input) ? input : {};
      Object.keys(record).forEach(function(group) {
        var key = String(group || "").trim().slice(0, 40);
        if (!key) return;
        var list = normalizeSavedButtonActions(record[group], 40);
        if (out[key] && out[key].length) {
          list.forEach(function(item) {
            var dup = false;
            for (var i = 0; i < out[key].length; i++) { if (savedActionSame(out[key][i], item)) { dup = true; break; } }
            if (!dup) out[key].push(item);
          });
        } else {
          out[key] = list;
        }
      });
      try {
        Object.keys(INSPECTOR_CUSTOM_GROUP_LEGACY_TARGETS).forEach(function(oldKey) {
          if (!record || !record[oldKey]) return;
          var targets = INSPECTOR_CUSTOM_GROUP_LEGACY_TARGETS[oldKey] || [];
          var srcList = out[oldKey] || normalizeSavedButtonActions(record[oldKey], 40);
          targets.forEach(function(target) {
            if (!target || target === oldKey) return;
            if (!out[target] || !out[target].length) {
              out[target] = (srcList || []).slice();
            } else {
              (srcList || []).forEach(function(item) {
                var dup = false;
                for (var i = 0; i < out[target].length; i++) { if (savedActionSame(out[target][i], item)) { dup = true; break; } }
                if (!dup && out[target].length < 40) out[target].push(item);
              });
            }
          });
          if (targets.indexOf(oldKey) === -1) delete out[oldKey];
        });
      } catch (e) {}
      // 诊断不显示右侧：丢弃旧 diagnostics 键（标题/section/运维遗留），运维提示并入主列诊断卡
      try { delete out["诊断与自检"]; delete out["diagnostics"]; delete out["运维"]; } catch (e) {}
      return out;
    }

    function inspectorCustomGroupsState() {
      var raw = (currentUiLayout && currentUiLayout.inspectorCustomGroups) || {};
      return normalizeInspectorCustomGroups(raw);
    }

    function inspectorCommandVisible(btn) {
      try {
        if (!btn || !btn.isConnected) return false;
        if (btn.hasAttribute && btn.hasAttribute("hidden")) return false;
        if (btn.closest && btn.closest("[hidden]")) return false;
        var st = null;
        try { st = window.getComputedStyle(btn); } catch (e) { st = null; }
        if (st && (st.display === "none" || st.visibility === "hidden" || st.opacity === "0")) return false;
        var card = (btn.closest && btn.closest("#mainColumn>[data-section]")) || null;
        if (card) {
          if (card.hasAttribute && card.hasAttribute("hidden")) return false;
          var cst = null;
          try { cst = window.getComputedStyle(card); } catch (e) { cst = null; }
          if (cst && (cst.display === "none" || cst.visibility === "hidden")) return false;
        }
        if (btn.classList && btn.classList.contains("is-collapsed")) return false;
        if (btn.offsetParent === null) {
          var pos = st ? String(st.position || "") : "";
          if (pos !== "fixed") return false;
        }
        return true;
      } catch (e) { return false; }
    }

    function inspectorVisibleCommandsForSection(section) {
      var out = new Set();
      try {
        if (typeof sectionIsCollapsed === "function" && sectionIsCollapsed(section)) return out;
        var card = null;
        try { card = document.querySelector('#mainColumn>[data-section="' + String(section || "") + '"]'); } catch (e) { card = null; }
        if (!card) return out;
        if (card.hasAttribute && card.hasAttribute("hidden")) return out;
        var cs = null;
        try { cs = window.getComputedStyle(card); } catch (e) { cs = null; }
        if (cs && (cs.display === "none" || cs.visibility === "hidden")) return out;
        var nodes = null;
        try { nodes = card.querySelectorAll("[data-command]"); } catch (e) { nodes = null; }
        if (!nodes) return out;
        Array.prototype.forEach.call(nodes, function(b) {
          if (!b) return;
          var cmd = (b.dataset && b.dataset.command) || (b.getAttribute ? b.getAttribute("data-command") : "") || "";
          if (!cmd) return;
          if (!inspectorCommandVisible(b)) return;
          out.add(String(cmd));
        });
      } catch (e) {}
      return out;
    }

    function inspectorCustomCandidatePool(groupTitle) {
      var seen = {};
      var pool = [];
      var sections = inspectorSectionsForCustomGroup(groupTitle);
      if (!sections.length) return [];
      var allowed = new Set();
      sections.forEach(function(section) {
        try {
          var vis = inspectorVisibleCommandsForSection(section);
          vis.forEach(function(cmd) { allowed.add(String(cmd)); });
        } catch (e) {}
      });
      if (!allowed.size) return [];
      var push = function(label, command, options) {
        if (!command) return;
        var finalLabel = label || featureCommandLabel(command) || command;
        var dedupeKey = String(command) + "|" + String(finalLabel);
        if (seen[dedupeKey]) return;
        if (typeof webviewHandledCommands !== "undefined" && webviewHandledCommands && !webviewHandledCommands.has(command)) return;
        if (!allowed.has(String(command))) return;
        seen[dedupeKey] = true;
        pool.push([finalLabel, command, options || {}]);
      };
      sections.forEach(function(section) {
        try {
          var actions = workbenchInspectorActions(section, { anchor: section });
          (actions || []).forEach(function(item) { push(item[0], item[1], item[2] || {}); });
        } catch (e) {}
      });
      pool.sort(function(a, b) { return String(a[0]).localeCompare(String(b[0])); });
      return pool;
    }

    function renderInspectorCustomGroups() {
      var titles = inspectorCustomGroupTitles();
      var groups = inspectorCustomGroupsState();
      return titles.map(function(title) {
        var items = (groups[title] || []).filter(function(spec) { return !["archiveArtifacts", "deleteArtifacts", "archivePlanCopy"].includes(spec.command); });
        var buttons = items.map(function(spec) {
          var btn = inspectorSavedActionButton(spec);
          var upBtn = '<button type="button" class="mini secondary inspectorCustomRowBtn" data-inspector-move="up" data-inspector-group="' + escAttr(title) + '" data-inspector-id="' + escAttr(spec.id) + '" title="上移">↑</button>';
          var downBtn = '<button type="button" class="mini secondary inspectorCustomRowBtn" data-inspector-move="down" data-inspector-group="' + escAttr(title) + '" data-inspector-id="' + escAttr(spec.id) + '" title="下移">↓</button>';
          var delBtn = '<button type="button" class="mini secondary inspectorCustomRowBtn" data-inspector-del="' + escAttr(spec.id) + '" data-inspector-group="' + escAttr(title) + '" title="删除">×</button>';
          return '<span class="inspectorActionRow">' + btn + upBtn + downBtn + delBtn + '</span>';
        }).join("");
        var emptyHint = items.length ? "" : '<div class="inspectorCustomEmpty">暂无按钮，点击下方添加。</div>';
        var inspectorGotoSection = "";
        try { var inspectorGotoSections = inspectorSectionsForCustomGroup(title); if (inspectorGotoSections && inspectorGotoSections.length) inspectorGotoSection = String(inspectorGotoSections[0] || ""); } catch (e) {}
        var inspectorGotoAttr = inspectorGotoSection ? ' data-inspector-goto="' + escAttr(inspectorGotoSection) + '"' : "";
        var inspectorGotoTip = inspectorGotoSection ? ' title="点击定位到主列' + escAttr(inspectorGotoSection) + '卡片"' : "";
        return '<div class="pinnedActions inspectorCustomGroup" data-custom-group="' + escAttr(title) + '"><div class="inspectorCustomGroupHead"' + inspectorGotoAttr + inspectorGotoTip + '><div class="inspectorEyebrow"' + inspectorGotoAttr + '>' + esc(title) + '（' + String(items.length) + '）</div><button type="button" class="mini secondary inspectorCustomRowBtn" data-inspector-add title="添加一行新按钮到自定义操作组"="' + escAttr(title) + '">+ 添加</button></div><div class="workflowActions">' + buttons + '</div>' + emptyHint + '</div>';
      }).join("");
    }

    function saveInspectorCustomGroups(next) {
      currentUiLayout = Object.assign({}, currentUiLayout, { inspectorCustomGroups: normalizeInspectorCustomGroups(next) });
      saveUiLayout({ preserveOrder: true });
      persistWebviewState({ inspectorCustomGroups: currentUiLayout.inspectorCustomGroups });
      forceWorkbenchInspectorRender();
      renderWorkbenchInspector(lastState || {}, { force: true });
    }

    function moveInspectorCustomButton(groupTitle, actionId, delta) {
      var groups = inspectorCustomGroupsState();
      var list = (groups[groupTitle] || []).slice();
      var idx = -1;
      for (var i = 0; i < list.length; i++) { if (String(list[i].id) === String(actionId)) { idx = i; break; } }
      if (idx === -1) return;
      var nextIdx = idx + delta;
      if (nextIdx < 0 || nextIdx >= list.length) return;
      var tmp = list[idx];
      list[idx] = list[nextIdx];
      list[nextIdx] = tmp;
      groups[groupTitle] = list;
      markWorkbenchInspectorInteraction(1600);
      saveInspectorCustomGroups(groups);
    }

    function deleteInspectorCustomButton(groupTitle, actionId) {
      var groups = inspectorCustomGroupsState();
      var list = (groups[groupTitle] || []).filter(function(item) { return String(item.id) !== String(actionId); });
      groups[groupTitle] = list;
      markWorkbenchInspectorInteraction(1600);
      saveInspectorCustomGroups(groups);
    }

    function openInspectorAddMenu(groupTitle, anchorEl) {
      var existing = el("inspectorAddMenu");
      if (existing && existing.getAttribute("data-inspector-menu-group") === String(groupTitle || "")) { closeInspectorAddMenu(); return; }
      closeInspectorAddMenu();
      var pool = inspectorCustomCandidatePool(groupTitle);
      var groups = inspectorCustomGroupsState();
      var picked = {};
      (groups[groupTitle] || []).forEach(function(item) { picked[item.command + "|" + item.label] = true; });
      var rows = pool.map(function(item, index) {
        var label = item[0];
        var command = item[1];
        var key = command + "|" + label;
        var checked = picked[key] ? " checked disabled" : "";
        var help = "";
        try { help = commandHelp(command) || ""; } catch (e) { help = ""; }
        return '<label title="' + escAttr(help || command) + '"><input type="checkbox" data-inspector-pick="' + escAttr(command) + '" data-inspector-label="' + escAttr(label) + '" value="' + String(index) + '"' + checked + '> ' + esc(label) + ' <span class="muted">' + esc(command) + '</span></label>';
      }).join("");
      if (!rows) rows = '<div class="muted">主列暂无可见按钮（未渲染或已折叠），请先展开主列对应卡片。</div>';
      var menu = document.createElement("div");
      menu.id = "inspectorAddMenu";
      menu.className = "inspectorAddMenu is-open";
      menu.setAttribute("data-inspector-menu-group", groupTitle);
      menu.innerHTML = '<div class="inspectorEyebrow">添加按钮到 ' + esc(groupTitle) + '</div><div style="display:grid;gap:4px;max-height:220px;overflow:auto;">' + rows + '</div><div style="display:flex;gap:6px;"><button type="button" data-inspector-confirm title="确认添加按钮到当前操作组"="' + escAttr(groupTitle) + '">确定</button><button type="button" class="secondary" data-inspector-cancel title="取消添加按钮，关闭弹窗"="1">取消</button></div>';
      document.body.appendChild(menu);
      try { document.body.classList.add("inspector-menu-open"); } catch (e) {}
      try {
        var rect = anchorEl && anchorEl.getBoundingClientRect ? anchorEl.getBoundingClientRect() : null;
        var menuWidth = 300;
        var menuHeight = 320;
        var left = rect ? rect.left : Math.max(8, window.innerWidth - menuWidth - 12);
        var top = rect ? rect.bottom + 6 : 80;
        if (rect) {
          if (left + menuWidth > window.innerWidth - 8) left = Math.max(8, window.innerWidth - menuWidth - 8);
          if (top + menuHeight > window.innerHeight - 8) top = Math.max(8, rect.top - menuHeight - 6);
          if (top < 8) top = 8;
          if (left < 8) left = 8;
        }
        menu.style.left = Math.max(8, Math.round(left)) + "px";
        menu.style.top = Math.max(8, Math.round(top)) + "px";
      } catch (e) {}
      markWorkbenchInspectorInteraction(5000);
    }

    function closeInspectorAddMenu() {
      var menu = el("inspectorAddMenu");
      if (menu && menu.parentNode) menu.parentNode.removeChild(menu);
      try { document.body.classList.remove("inspector-menu-open"); } catch (e) {}
    }

    function confirmInspectorAddMenu(groupTitle) {
      var menu = el("inspectorAddMenu");
      if (!menu) return;
      var picks = Array.from(menu.querySelectorAll("input[data-inspector-pick]:checked:not(:disabled)"));
      if (!picks.length) { closeInspectorAddMenu(); return; }
      var groups = inspectorCustomGroupsState();
      var list = (groups[groupTitle] || []).slice();
      picks.forEach(function(input) {
        var command = input.getAttribute("data-inspector-pick") || "";
        var label = input.getAttribute("data-inspector-label") || featureCommandLabel(command) || command;
        var pool = inspectorCustomCandidatePool(groupTitle);
        var found = null;
        for (var i = 0; i < pool.length; i++) { if (String(pool[i][1]) === String(command) && String(pool[i][0]) === String(label)) { found = pool[i]; break; } }
        var spec = normalizeSavedButtonAction({ command: command, label: label, section: "overview", payload: found ? (found[2] && found[2].payload ? found[2].payload : {}) : {}, confirm: found && found[2] ? Boolean(found[2].confirm) : false, danger: found && found[2] ? Boolean(found[2].danger) : false, batch: found && found[2] ? Boolean(found[2].batch) : false, configScope: found && found[2] ? String(found[2].configScope || "") : "" });
        if (spec && !list.some(function(item) { return savedActionSame(item, spec); })) list.push(spec);
      });
      groups[groupTitle] = list.slice(0, 40);
      closeInspectorAddMenu();
      saveInspectorCustomGroups(groups);
    }

    function applyLayoutColumns() {
      const deck = el("cardDeck");
      if (!deck) return;
      const columns = normalizeLayoutColumns(currentUiLayout.columns || {});
      deck.style.setProperty("--tree-col", columns.tree + "px");
      deck.style.setProperty("--inspector-col", columns.inspector + "px");
      applyDrawerPinState();
    }

    function toggleDrawerPinned(side) {
      if (side !== "tree" && side !== "inspector") return;
      const key = side === "tree" ? "treePinned" : "inspectorPinned";
      currentUiLayout[key] = !currentUiLayout[key];
      if (side === "inspector" && !currentUiLayout[key]) { try { closeInspectorAddMenu(); } catch (e) {} }
      applyDrawerPinState();
      saveUiLayout({ preserveOrder: true });
    }

    function applyDrawerPinState() {
      const wasInspectorPinned = document.body.classList.contains("inspector-pinned");
      const treePinned = Boolean(currentUiLayout.treePinned);
      const inspectorPinned = Boolean(currentUiLayout.inspectorPinned);
      document.body.classList.toggle("tree-pinned", treePinned);
      document.body.classList.toggle("inspector-pinned", inspectorPinned);
      if (wasInspectorPinned && !inspectorPinned) { try { closeInspectorAddMenu(); } catch (e) {} }
      document.querySelectorAll("[data-drawer-pin]").forEach((button) => {
        const pinned = button.dataset.drawerPin === "tree" ? treePinned : button.dataset.drawerPin === "inspector" ? inspectorPinned : false;
        const label = button.dataset.drawerPin === "tree" ? "左侧目录" : "右侧详情";
        button.classList.toggle("is-pinned", pinned);
        button.setAttribute("aria-pressed", String(pinned));
        setNativeTitle(button, (pinned ? "取消固定" : "固定") + label);
        button.setAttribute("aria-label", button.title);
      });
      syncPanelSectionInterest();
    }

    function setNativeTitle(node, value) {
      if (!node || !node.getAttribute || !node.setAttribute) return false;
      const next = String(value || "");
      const current = String(node.getAttribute("title") || "");
      if (current === next) return false;
      if (next) node.setAttribute("title", next);
      else node.removeAttribute("title");
      nativeTitleMutationVersion = (nativeTitleMutationVersion + 1) % 1000000;
      return true;
    }

    function setAllSectionsCollapsed(collapsed) {
      try { closeInspectorAddMenu(); } catch (e) {}
      document.querySelectorAll("#mainColumn > [data-section]").forEach((card) => card.classList.toggle("is-collapsed", collapsed));
      currentUiLayout.collapsed = collapseStateFromDom();
      explicitlyExpandedInterestSections.clear();
      if (!collapsed) sectionRenderOrder.forEach((section) => explicitlyExpandedInterestSections.add(section));
      visiblePanelSections = collectVisiblePanelSections();
      syncPanelSectionInterest();
      saveUiLayout({ preserveOrder: true });
      renderResourceTree(lastState || {});
    }

    function expandResourceSection(section) {
      const card = document.querySelector('#mainColumn [data-section="' + cssEscape(section) + '"]');
      if (!card || !card.classList.contains("is-collapsed")) return;
      currentUiLayout.collapsed = Object.assign({}, currentUiLayout.collapsed, { [section]: false });
      applyUiLayout({ uiLayout: currentUiLayout });
      renderSectionIfVisible(lastState || {}, section, { force: true });
      saveUiLayout({ preserveOrder: true });
    }

    function applyMainViewForSection(section) {
      const nextView = section === "settings" ? "settings" : "workspace";
      if (nextView === "settings" && currentMainView !== "settings" && activeResourceSection !== "settings") {
        lastWorkspaceResource = { section: activeResourceSection || "overview", anchor: activeResourceAnchor || activeResourceSection || "overview" };
      }
      currentMainView = nextView;
      document.body.classList.toggle("main-view-settings", currentMainView === "settings");
    }

    function switchMainView(view) {
      if (view === "settings") {
        applyMainViewForSection("settings");
        expandResourceSection("settings");
        activeResourceSection = "settings";
        activeResourceAnchor = "settings";
        renderSectionIfVisible(lastState || {}, "settings", { force: true });
      } else {
        currentMainView = "workspace";
        document.body.classList.remove("main-view-settings");
        activeResourceSection = lastWorkspaceResource.section || "overview";
        activeResourceAnchor = lastWorkspaceResource.anchor || activeResourceSection;
      }
      resourceTreeRenderKey = "";
      renderResourceTree(lastState || {});
      updateResourceTreeActiveSection(activeResourceSection, activeResourceAnchor);
      forceWorkbenchInspectorRender();
      renderWorkbenchInspector(lastState || {}, { force: true });
      renderVisibleSections(lastState || {});
      requestAnimationFrame(() => scrollToResourceTarget(activeResourceSection, activeResourceAnchor));
    }

    // legacy pinned-command context menu removed; status-card menu (showStatusCardContextMenu) remains.

    function actionSpecFromButton(button) {
      if (!button) return null;
      const command = String(button.dataset.command || "");
      if (!command || !webviewHandledCommands?.has(command)) return null;
      const sourceSection = button.dataset.actionSection || (button.closest("#mainColumn [data-section]") || {}).dataset?.section || activeResourceSection || "overview";
      const payload = buttonDatasetActionPayload(button);
      const label = cleanButtonLabel(button) || featureCommandLabel(command) || command;
      return normalizeSavedButtonAction({
        id: button.dataset.actionId || actionSpecId(command, normalizeActionSection(sourceSection), payload, label),
        command,
        label,
        section: sourceSection,
        payload,
        confirm: button.dataset.confirm === "true",
        danger: button.dataset.danger === "true",
        batch: button.dataset.batchSelected === "true",
        configScope: button.dataset.configScope || ""
      });
    }

    function cleanButtonLabel(button) {
      const clone = button.cloneNode(true);
      clone.querySelectorAll && clone.querySelectorAll(".loading-spinner").forEach((node) => node.remove());
      return String(clone.textContent || "").replace(/\\s+/g, " ").trim();
    }

    function buttonDatasetActionPayload(button) {
      const payload = {};
      ["tableKey", "artifactKey", "format", "endpointId", "planFile", "planRevision", "planId", "deferredPlanId", "file", "report", "name", "runKey", "taskUiKey", "experimentId", "archiveKey", "experimentIndex", "gpuId", "workerId", "remotePath", "confirmationPath", "artifactPath", "resultPath", "logPath", "savePlan", "target", "session", "window"].forEach((key) => {
        if (button.dataset[key]) payload[key] = button.dataset[key];
      });
      if (button.dataset.batchSelected === "true") payload.batchSelected = "true";
      return payload;
    }

    function showStatusCardContextMenu(card, x, y) {
      const menu = el("pinContextMenu");
      if (!menu || !card) return;
      const key = statusCardKey(card);
      const collapsed = Boolean(collapsedStatusCards[key]);
      const label = statusCardLabel(card);
      menu.innerHTML =
        '<button type="button" data-card-menu-action="' + escAttr(collapsed ? "expand" : "collapse") + '" data-card-key="' + escAttr(key) + '" role="menuitem">' + esc(collapsed ? "展开此卡片" : "折叠此卡片") + '</button>' +
        '<button type="button" data-card-menu-action="expand" title="展开所有状态卡片，查看完整状态详情" data-card-key="__all__" role="menuitem">展开全部状态卡片</button>';
      setNativeTitle(menu, "右键状态卡片：" + label);
      menu.hidden = false;
      menu.classList.add("is-open");
      menu.dataset.open = "1";
      const width = 190;
      const height = 76;
      menu.style.left = Math.max(8, Math.min(x, window.innerWidth - width - 8)) + "px";
      menu.style.top = Math.max(8, Math.min(y, window.innerHeight - height - 8)) + "px";
    }

    function setStatusCardCollapsed(key, collapsed) {
      if (!key) return;
      if (key === "__all__") collapsedStatusCards = {};
      else {
        const current = Boolean(collapsedStatusCards[key]);
        const next = collapsed === undefined ? !current : collapsed;
        if (next) collapsedStatusCards[key] = true;
        else delete collapsedStatusCards[key];
      }
      statusCardCollapseVersion = (statusCardCollapseVersion + 1) % 1000000;
      applyStatusCardCollapseState();
    }

    function applyStatusCardCollapseState() {
      const collapsedKey = Object.keys(collapsedStatusCards).sort().join("|");
      const scanKey = [postRenderDomVersion, statusCardCollapseVersion, collapsedKey].join("::");
      if (scanKey === lastStatusCollapseScanKey) return;
      lastStatusCollapseScanKey = scanKey;
      const cards = Array.from(document.querySelectorAll(statusCardSelector()));
      const nextKey = [
        cards.length,
        cards.filter((card) => !card.dataset.statusCardKey).length,
        collapsedKey
      ].join("::");
      if (nextKey === lastStatusCollapseKey) return;
      lastStatusCollapseKey = nextKey;
      cards.forEach((card) => {
        const key = statusCardKey(card);
        card.dataset.statusCardKey = key;
        card.classList.toggle("statusCardCollapsed", Boolean(collapsedStatusCards[key]));
      });
    }

    function statusCardSelector() {
      return "#mainColumn .planRunRow, #mainColumn .task-card, #mainColumn .traceCard, #mainColumn .operationItem, #mainColumn .endpointStatusCard, #mainColumn .serverObjectCard, #mainColumn .resultEvidenceRow, #mainColumn .objectTile, #mainColumn .taskProgressCard, #mainColumn .gpuServer, #mainColumn .targetMatrixRow, #mainColumn .featureAuditPill, #mainColumn .capabilityItem";
    }

    function statusCardKey(card) {
      return String(card.dataset.statusCardKey || card.dataset.anchor || card.id || (Array.from(card.classList || []).filter((name) => name !== "statusCardCollapsed").join(".") + ":" + statusCardLabel(card))).slice(0, 180);
    }

    function statusCardLabel(card) {
      const text = (card.querySelector("h3,h4,b,.objectTileHead,.gpuServerTitle") || card).textContent || "状态卡片";
      return text.replace(/\\s+/g, " ").trim().slice(0, 80) || "状态卡片";
    }

    function hidePinContextMenu() {
      const menu = el("pinContextMenu");
      if (!menu) return;
      if (menu.dataset.open !== "1" && menu.hidden) return;
      menu.classList.remove("is-open");
      menu.hidden = true;
      delete menu.dataset.open;
      menu.innerHTML = "";
    }

    function beginLayoutResize(kind, event) {
      activeLayoutResize = { kind, startX: event.clientX, start: normalizeLayoutColumns(currentUiLayout.columns || {}) };
      document.body.classList.add("resizing-layout");
      event.preventDefault();
    }

    function updateLayoutResize(event) {
      if (!activeLayoutResize) return;
      try { closeInspectorAddMenu(); } catch (e) {}
      const delta = event.clientX - activeLayoutResize.startX;
      const columns = normalizeLayoutColumns(activeLayoutResize.start);
      if (activeLayoutResize.kind === "tree") columns.tree = clampNumber(activeLayoutResize.start.tree + delta, 220, 420);
      if (activeLayoutResize.kind === "inspector") columns.inspector = clampNumber(activeLayoutResize.start.inspector - delta, 280, 520);
      currentUiLayout.columns = columns;
      applyLayoutColumns();
    }

    function finishLayoutResize() {
      if (!activeLayoutResize) return;
      activeLayoutResize = null;
      document.body.classList.remove("resizing-layout");
      saveUiLayout({ preserveOrder: true });
    }

    function updateLayoutToggle() {
      const button = el("layoutEditToggle");
      if (button) button.textContent = layoutEdit ? "完成布局" : "管理布局";
    }

    function renderResourceTree(_state) {
      // 顶级=卡片标题直摆（无 label 分组头），顺序沿用 RESOURCE_TREE_SECTION_ORDER 经 normalizeUiLayout；servers 隐藏跳过（合入 sync）。
      const order = [...new Set(normalizeUiLayout(currentUiLayout).order)].filter((section) => section !== "servers" && section !== "settings");
      const nextRenderKey = resourceTreeNextRenderKey(order);
      if (!resourceTreeNeedsRerender(nextRenderKey)) {
        updateResourceTreeActiveSection(activeResourceSection, activeResourceAnchor);
        return;
      }
      const groupsBySection = resourceTreeStaticModelCached();
      const groups = order.map((section) => {
        const entry = groupsBySection[section];
        return entry ? { label: entry.label, tone: normalizeTreeTone(entry.node.tone), items: [entry.node] } : null;
      }).filter(Boolean);
      resourceTreeMeta = {};
      registerResourceTreeNodes(groups.flatMap((group) => group.items));
      updateResourceTreeHead("");
      const query = resourceTreeFilter;
      const filtered = groups.map((group) => {
        if (!query) return group;
        const items = group.items.filter((node) => resourceTreeSearchText(node).includes(query));
        return Object.assign({}, group, { items });
      }).filter((group) => group.items.length);
      const body = el("resourceTreeBody");
      if (!body) return;
      setHtmlIfChanged(body, filtered.length ? filtered.map((group) =>
        '<div class="tree-group ' + escAttr(group.tone || "") + '">' + group.items.map(renderResourceTreeNode).join("") + '</div>'
      ).join("") : '<div class="tree-empty">没有匹配条目。可以搜索“GPU / 任务 / GitHub / SFTP / Agent / 删除 / 归档”。</div>');
      const search = el("resourceTreeSearch");
      if (search && search.value !== resourceTreeFilter) search.value = resourceTreeFilter;
      updateResourceTreeActiveSection(activeResourceSection, activeResourceAnchor);
      renderResourceTreeInspector(activeResourceSection, activeResourceAnchor);
    }

    function resourceTreeStaticModelCached() {
      if (!resourceTreeStaticModelCache) resourceTreeStaticModelCache = resourceTreeStaticModel();
      return resourceTreeStaticModelCache;
    }

    function resourceTreeStaticModel() {
      // 资源树顶级=主列卡片标题直摆（无 发布/实验/资源/执行/运维/基础设施 label 一级），顺序沿用 RESOURCE_TREE_SECTION_ORDER；servers 隐藏合入 sync。
      const item = (section, label, title, icon, detail, searchText, anchor) => {
        return treeItem(section, label, title, icon, "", "", searchText, anchor, detail);
      };
      return {
        servers: { label: "运行环境准备", node: withResourceTreeChildren(item("servers", "服务器管理", "服务器管理", "▦", "Hub/Worker/端口", "Hub Worker Xshell 端口 调度"), serverTreeObjects()) },
        gpu: { label: "GPU 状态", node: withResourceTreeChildren(item("gpu", "GPU 状态", "GPU 总览", "◫", "GPU 总览", "GPU 显卡 显存 温度 利用率 我的任务 进程"), gpuTreeObjects()) },
        tmux: { label: "TMUX 会话 / 窗口 / 窗格", icon: RESOURCE_TREE_SECTION_ICONS.tmux || "⬢", node: withResourceTreeChildren(item("tmux", "TMUX 会话 / 窗口 / 窗格", "TMUX 会话 / 窗口 / 窗格", RESOURCE_TREE_SECTION_ICONS.tmux || "⬢", "会话/窗口/窗格", "tmux 会话 窗口 窗格 会话总览"), tmuxTreeObjects()) },
        plans: { label: "实验准备", node: withResourceTreeChildren(item("plans", "实验准备", "实验计划", "◇", "计划/校验/运行", "计划 参数 校验 预演 运行"), planTreeObjects()) },
        execution: { label: "运行进度", node: withResourceTreeChildren(item("execution", "运行进度", "调度操作与实验任务统一视图", "▣", "操作+任务/日志/终态", "任务 日志 停止 重试 删除 归档 排队 运行 操作 进度 已提交 执行中 失败 卡住 已完成 accepted running failed stalled completed"), executionTreeObjects()) },
        results: { label: "结果文件", node: withResourceTreeChildren(item("results", "结果文件", "结果分析", "▤", "总表/方法表/原始数据", "结果 统计 质量门禁 论文 表格 CSV JSON"), resultTreeObjects()) },
        sync: { label: "运行环境准备", node: withResourceTreeChildren(item("sync", "运行环境准备", "运行环境准备 发布同步", "⇅", "三步链/三步动作/总览 + GitHub/SFTP/Agent", "运行环境准备 部署Agent 启动隧道 检测 三步链 三步动作 Git GitHub SFTP 上传 分发 Agent 部署 发布 同步"), syncTreeObjects()) },
        diagnostics: { label: "诊断与自检", node: withResourceTreeChildren(item("diagnostics", "诊断与自检", "诊断", "⌁", "能力/端口/审计", "诊断 自检 调试 审计 能力 端口"), diagnosticTreeObjects()) }
      };
    }

    function resourceTreeNextRenderKey(order) {
      const normalizedOrder = (order || []).join("|");
      const collapsed = Object.entries((currentUiLayout && currentUiLayout.collapsed) || {}).sort(([a], [b]) => naturalCompare(a, b)).map(([key, value]) => key + ":" + (value ? "1" : "0")).join("|");
      return [normalizedOrder, collapsed, resourceTreeChildOrderSignature(), resourceTreeFilter].join("::");
    }

    function resourceTreeChildOrderSignature(layout) {
      const source = layout || currentUiLayout || {};
      const orders = normalizeResourceTreeChildOrders(source.resourceTreeChildren || {});
      return Object.keys(orders).sort((a, b) => naturalCompare(a, b)).map((section) => section + "=" + orders[section].join("|")).join(";");
    }

    function resourceTreeNeedsRerender(nextKey) {
      if (nextKey === resourceTreeRenderKey) return false;
      resourceTreeRenderKey = nextKey;
      return true;
    }

    function resourceTreeNode(input) {
      const node = input || {};
      const section = String(node.section || node.id || "");
      const anchor = String(node.anchor || section);
      const label = String(node.label || section || "对象");
      const tooltip = String(node.tooltip || node.title || node.detail || label);
      const status = node.status == null ? "" : String(node.status);
      const count = node.count == null ? "" : String(node.count);
      const children = normalizeResourceTreeChildren(node.children);
      const kind = String(node.kind || "object");
      return {
        id: String(node.id || anchor || section),
        label,
        kind,
        icon: String(node.icon || (kind === "object" ? defaultTreeObjectIcon(section) : "")),
        tone: normalizeTreeTone(node.tone),
        status,
        count,
        section,
        anchor,
        tooltip,
        title: tooltip,
        detail: String(node.detail || tooltip),
        searchText: [section, anchor, label, status, count, tooltip, node.searchText || "", children.map(resourceTreeSearchText).join(" ")].join(" ").toLowerCase(),
        children
      };
    }

    function normalizeResourceTreeChildren(children) {
      return asArray(children || []).filter(Boolean).map((child) => resourceTreeNode(child));
    }

    function withResourceTreeChildren(node, children) {
      return resourceTreeNode(Object.assign({}, node, { children: normalizeResourceTreeChildren(children) }));
    }

    function treeItem(section, label, title, icon, count, tone, searchText, anchor, detail) {
      return resourceTreeNode({ id: anchor || section, label, kind: "section", icon, tone, count, status: count || "", section, anchor: anchor || section, tooltip: title, detail: detail || title, searchText });
    }

    function treeChildList(children) {
      const rows = normalizeResourceTreeChildren(children);
      const ordered = orderedResourceTreeChildren(rows, rows[0] ? rows[0].section : "");
      return ordered.length ? '<div class="tree-child-list">' + ordered.map(renderResourceTreeNode).join("") + '</div>' : "";
    }

    function treeObjectItem(section, label, status, tone, title, anchor, icon, searchExtra) {
      return resourceTreeNode({ id: anchor || section, label, kind: "object", icon, tone, status: "", count: "", section, anchor: anchor || section, tooltip: title || label, detail: title || "", searchText: [status || "", searchExtra || ""].join(" ") });
    }

    function orderedResourceTreeChildren(children, section) {
      const rows = normalizeResourceTreeChildren(children);
      const saved = resourceTreeCustomChildOrder(section);
      if (!saved.length) return rows;
      const byAnchor = new Map(rows.map((row) => [row.anchor, row]));
      return saved.map((anchor) => byAnchor?.get(anchor)).filter(Boolean)
        .concat(rows.filter((row) => !saved.includes(row.anchor)));
    }

    function resourceTreeCustomChildOrder(section) {
      return normalizeResourceTreeChildOrders((currentUiLayout && currentUiLayout.resourceTreeChildren) || {})[section] || [];
    }

    function resourceTreeSectionHasCustomChildOrder(section) {
      return resourceTreeCustomChildOrder(section).length > 0;
    }

    function resourceTreeChildrenForSection(section) {
      const model = resourceTreeStaticModelCached();
      const entry = model[String(section || "")];
      return orderedResourceTreeChildren(entry && entry.node ? entry.node.children : [], section).map((node) => node.anchor);
    }

    function defaultTreeObjectIcon(section) {
      return RESOURCE_TREE_SECTION_ICONS[section] || "•";
    }

    function renderResourceTreeNode(node) {
      const normalized = resourceTreeNode(node);
      const isSection = normalized.kind === "section";
      const current = normalized.section === activeResourceSection && normalized.anchor === activeResourceAnchor ? " is-current" : "";
      if (isSection) {
        const hot = normalized.tone ? " is-hot " + normalized.tone : "";
        return '<button type="button" class="tree-item' + hot + current + '" draggable="true" data-tree-order-section="' + escAttr(normalized.section) + '" data-section-target="' + escAttr(normalized.section) + '" data-anchor-target="' + escAttr(normalized.anchor) + '" data-search-text="' + escAttr(resourceTreeSearchText(normalized)) + '" title="' + escAttr(normalized.tooltip) + '" aria-current="' + (current ? "true" : "false") + '">' +
          '<span class="tree-icon" aria-hidden="true">' + esc(normalized.icon) + '</span><span class="tree-label">' + esc(normalized.label) + '</span>' +
        '</button>' + treeChildList(normalized.children);
      }
      return '<button type="button" class="tree-object ' + escAttr(normalized.tone) + current + '" draggable="true" data-tree-child-section="' + escAttr(normalized.section) + '" data-tree-child-anchor="' + escAttr(normalized.anchor) + '" data-section-target="' + escAttr(normalized.section) + '" data-anchor-target="' + escAttr(normalized.anchor) + '" data-search-text="' + escAttr(resourceTreeSearchText(normalized)) + '" title="' + escAttr(normalized.tooltip) + '">' +
        '<span class="tree-object-icon" aria-hidden="true">' + esc(normalized.icon) + '</span><span class="tree-object-label">' + esc(normalized.label) + '</span>' +
      '</button>';
    }

    function registerResourceTreeNodes(nodes) {
      normalizeResourceTreeChildren(nodes).forEach((node) => {
        const meta = { id: node.id, kind: node.kind, section: node.section, anchor: node.anchor, label: node.label, title: node.tooltip, icon: node.icon, count: node.count || node.status || "", status: node.status || "", tone: node.tone, detail: node.detail || node.tooltip, searchText: resourceTreeSearchText(node) };
        resourceTreeMeta[resourceTreeMetaKey(node.section, node.anchor)] = meta;
        if (!resourceTreeMeta[node.anchor]) resourceTreeMeta[node.anchor] = meta;
        if (!resourceTreeMeta[node.section]) resourceTreeMeta[node.section] = meta;
        registerResourceTreeNodes(node.children);
      });
    }

    function resourceTreeMetaKey(section, anchor) {
      return String(section || "") + "::" + String(anchor || section || "");
    }

    function normalizeTreeTone(tone) {
      const value = String(tone || "").toLowerCase();
      return RESOURCE_TREE_TONE_VALUES?.has(value) ? value : "";
    }

    function resourceTreeDominantTone(tones) {
      return (tones || []).map(normalizeTreeTone).filter(Boolean).sort((a, b) => (RESOURCE_TREE_TONE_RANKS[b] || 0) - (RESOURCE_TREE_TONE_RANKS[a] || 0))[0] || "";
    }

    function updateResourceTreeHead(tone) {
      const head = el("resourceTreeHead");
      if (!head) return;
      const normalizedTone = normalizeTreeTone(tone);
      head.className = "tree-head" + (normalizedTone ? " " + normalizedTone : "");
      setNativeTitle(head, resourceTreeGroupToneHelp(normalizedTone));
    }

    function resourceTreeGroupToneHelp(tone) {
      return RESOURCE_TREE_TONE_HELP[normalizeTreeTone(tone)] || "浅灰色：当前区域无需要分级的状态。";
    }

    function resourceTreeSearchText(html) {
      if (html && typeof html === "object") {
        const node = html;
        const cached = resourceTreeSearchTextCache?.get(node);
        if (typeof cached === "string") return cached;
        const value = [node.id, node.label, node.kind, node.icon, node.tone, node.status, node.count, node.section, node.anchor, node.tooltip, node.searchText, asArray(node.children || []).map(resourceTreeSearchText).join(" ")].join(" ").toLowerCase();
        resourceTreeSearchTextCache.set(node, value);
        return value;
      }
      const values = [];
      String(html || "").replace(/data-search-text="([^"]*)"/g, (_match, value) => {
        values.push(String(value || ""));
        return "";
      });
      return values.join(" ").toLowerCase();
    }

    function treeAnchorId(prefix, value) {
      const body = String(value || "")
        .toLowerCase()
        .replace(/[^a-z0-9\u4e00-\u9fa5_-]+/g, "-")
        .replace(/^-+|-+$/g, "")
        .slice(0, 64);
      return prefix + (body ? "-" + body : "");
    }

    function overviewHealthText(state) {
      const health = String((state.health || {}).state || "").toLowerCase();
      if (OVERVIEW_HEALTHY_STATUS_TOKENS?.has(health)) return "正常";
      if (health) return labelStatus(health);
      return "待检测";
    }

    function workflowStageText(state) {
      const project = state.detectedProject || {};
      if (asArray(project.resultFiles || []).length) return "结果";
      if (schedulerRowsForState(state).length) return "运行";
      if (asArray(project.plans || []).length) return "计划";
      return "接入";
    }

